   a,b=q.pop();cells.append((a,b))
   for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
    if 0<=x<H and 0<=y<W and (x,y) not in seen and grid[x][y]==v:seen.add((x,y));q.append((x,y))
